  const accessibleParts = svg.getAttribute('aria-labelledby').trim().split(/\s+/);
  expect(accessibleParts).toHaveLength(2);
  accessibleParts.forEach(id => expect(figure.querySelector('[id="' + id + '"]')?.textContent.trim()).toBeTruthy());
